      faq: {
        id: 'faq',
        title: 'Häufig gestellte Fragen',
        faqs: [
          { q: 'Was ist tgpt?', a: 'tgpt ([github.com/aandrew-me/tgpt](https://github.com/aandrew-me/tgpt)) ist ein kostenloses, quelloffenes (GPLv3), in Go geschriebenes Kommandozeilen-KI-Chatbot-Tool, das standardmäßig ohne eigenen API-Schlüssel funktioniert.' },
          { q: 'Wie funktioniert tgpt ohne API-Schlüssel?', a: 'Der Standardanbieter, "opencode," leitet Ihre Anfrage über einen kostenlosen öffentlichen Proxy (die "zen"-API von opencode.ai) mit einem gemeinsam genutzten öffentlichen Schlüssel statt eines persönlichen Kontos — das ist der spezifische Mechanismus, keine Umgehung der Nutzungsbedingungen eines Anbieters.' },
          { q: 'Ist der kostenlose Modus von tgpt zuverlässig?', a: 'Für den kostenlosen Standardmodus existiert keine veröffentlichte Rate-Limit-Garantie oder Uptime-SLA. tgpts eigener Issue-Tracker dokumentiert über seine Geschichte hinweg wiederholte Rate-Limit- und Gateway-Fehler bei kostenlosen Backends, weshalb ein `--rotate`-Fallback-Flag existiert.' },
          { q: 'Kann ich meinen eigenen API-Schlüssel mit tgpt verwenden?', a: 'Ja, tgpt unterstützt Bring-your-own-Key-Optionen für Anbieter einschließlich OpenAI, DeepSeek, Groq und Gemini, über das `--provider`-Flag.' },
          { q: 'Wer pflegt tgpt?', a: 'Ein Entwickler mit dem GitHub-Handle aandrew-me, wobei das Repository am 17. April 2023 erstellt wurde.' },
          { q: 'Unter welcher Lizenz wird tgpt veröffentlicht?', a: 'GNU General Public License v3.0 (GPLv3), bestätigt über die LICENSE-Datei des Repositorys.' },
          { q: 'Generiert tgpt Shell-Befehle wie shell-gpt?', a: 'Ja, das `-s`/`--shell`-Flag von tgpt generiert betriebssystembewusste Shell-Befehle aus natürlichsprachlichen Anfragen, vom Prinzip her ähnlich der Kernfunktion von shell-gpt.' },
          { q: 'Unterstützt tgpt Bildgenerierung?', a: 'Ja, über das `-img`/`--image`-Flag, unter Verwendung von Anbietern einschließlich pollinations, magicstudio und anyapi, gemäß eigener Dokumentation.' },
          { q: 'Ist tgpt ein autonomer Coding-Agent?', a: 'Nein, tgpt generiert Chat-Antworten, Shell-Befehle und Code-Schnipsel — es führt keine autonomen Änderungen über mehrere Dateien eines Projekts durch.' },
          { q: 'Hat PromptQuorum die Behauptungen von tgpt unabhängig getestet?', a: 'Diese Review basiert auf tgpts eigenem GitHub-Repository, seinem README, seiner Dokumentation im Repository und seinem öffentlichen Issue-Tracker, statt auf praktischen Benchmarks von PromptQuorum.' },
          { q: 'Ist tgpt dasselbe wie ChatGPT?', a: 'Nein. tgpt ist ein unabhängiges, quelloffenes Terminal-Programm, das von aandrew-me gepflegt wird, und kein Produkt von OpenAI. Es erreicht OpenAI-Modelle nur, wenn Sie den Anbieter `openai` wählen und Ihren eigenen API-Key angeben.' },
          { q: 'Ist tgpt offiziell, und wo bekomme ich es?', a: 'Die offizielle Quelle ist das GitHub-Repository des Projekts unter [github.com/aandrew-me/tgpt](https://github.com/aandrew-me/tgpt), wo auch die Installationsbefehle stehen. "Offiziell" ist es nur als Projekt des Maintainers; es ist kein offizieller Client von ChatGPT, OpenAI oder einem anderen KI-Anbieter.' },
          { q: 'Muss ich mich anmelden oder ein Konto erstellen, um tgpt zu nutzen?', a: 'Nein. tgpt hat weder Login noch Konto. Im Standardmodus nutzt es einen gemeinsamen öffentlichen Schlüssel: installieren und einen Prompt eingeben genügt. Nur Bring-your-own-Key-Anbieter wie OpenAI oder DeepSeek benötigen einen Schlüssel des jeweiligen Anbieters.' },
          { q: 'Welches KI-Modell verwendet tgpt?', a: 'Das hängt vom Anbieter ab. Beim kostenlosen Standard "opencode" hat sich das Modell zwischen Releases geändert — die Projektdokumentation nennt deepseek-v4-flash-free, der eingebaute Standard im Quellcode ist `big-pickle`. Mit `OPENCODE_MODEL` legen Sie eines fest, oder Sie wählen mit `--provider` einen anderen Anbieter.' },
          { q: 'Ist tgpt wirklich kostenlos?', a: 'Das Programm ist kostenlos und steht unter der GPLv3; der Standardmodus kostet nichts und braucht keinen Schlüssel. Anbieter, die Sie mit eigenem Schlüssel verbinden, rechnen direkt mit Ihnen ab, und für das kostenlose Standard-Backend gibt es keine veröffentlichte Rate-Limit-Garantie.' },
          { q: 'Läuft tgpt unter Linux und auf einem Chromebook?', a: 'Linux wird unterstützt: per Installationsskript, `pacman -S tgpt` unter Arch Linux, Homebrew oder Go. Ein Chromebook mit aktiviertem Linux (Crostini) führt Linux-Programme aus, die Linux-Installation sollte also funktionieren; PromptQuorum hat tgpt auf einem Chromebook jedoch nicht getestet.' },
          { q: 'Was bedeutet der Fehler "Invalid provider" in tgpt?', a: 'Der an `--provider` übergebene Name ist kein unterstützter Anbieter. Verwenden Sie den exakten kleingeschriebenen Namen aus der [Anbieterliste](https://github.com/aandrew-me/tgpt/blob/main/md/providers.md), zum Beispiel `opencode`, `pollinations` oder `groq`.' },
          { q: 'Warum liefert tgpt einen Fehler oder keine Antwort?', a: 'Meist ist das kostenlose Standard-Backend nicht erreichbar oder limitiert — ein Issue dazu war vom 14. bis 23. September 2026 mit v2.14.0 offen, bis v2.15.0 einen Fix brachte. Aktualisieren Sie tgpt, probieren Sie `--rotate` oder einen anderen Anbieter und prüfen Sie Netzwerk- und Proxy-Einstellungen. Siehe den Abschnitt zur Fehlerbehebung oben.' },
          { q: 'Wofür steht tgpt?', a: 'Das README definiert den Namen nicht; üblich ist die Lesart "terminal GPT". Das Repository beschreibt tgpt als plattformübergreifendes CLI-Tool, um KI im Terminal zu nutzen.' },
        ],
      },
