        content: '**La plupart des erreurs de tgpt viennent du backend gratuit par défaut indisponible, d\'un nom de fournisseur mal saisi ou d\'un problème de réseau ou de proxy — pas d\'une connexion manquante, car tgpt n\'a pas de compte auquel se connecter.**',
