        answer: 'El proveedor por defecto de tgpt, llamado "opencode," enruta tu prompt a través de un proxy público gratuito (la API "zen" de opencode.ai) usando una clave pública compartida en lugar de una personal — así es exactamente como funciona el modo "sin clave API necesaria", no es magia ni una forma de saltarse los términos de ningún proveedor. Este modo gratuito no tiene una garantía publicada de límite de tasa ni un SLA de disponibilidad, y el propio seguimiento de incidencias de tgpt documenta errores repetidos de límite de tasa y de puerta de enlace en backends gratuitos a lo largo de la historia del proyecto, razón por la cual la herramienta también admite un indicador de respaldo `--rotate` y más de 18 proveedores alternativos, incluidas opciones de clave API propia.',
