      faq: {
        id: 'faq',
        title: 'Perguntas frequentes',
        faqs: [
          { q: 'O que é o tgpt?', a: 'tgpt ([github.com/aandrew-me/tgpt](https://github.com/aandrew-me/tgpt)) é uma ferramenta de chatbot de IA por linha de comando, gratuita, de código aberto (GPLv3) e baseada em Go, que funciona sem exigir sua própria chave de API por padrão.' },
          { q: 'Como o tgpt funciona sem chave de API?', a: 'Seu provedor padrão, "opencode," encaminha seu prompt por um proxy público gratuito (a API "zen" da opencode.ai) usando uma chave compartilhada em vez de uma conta pessoal — esse é o mecanismo específico, não uma forma de burlar os termos de nenhum provedor.' },
          { q: 'O modo gratuito do tgpt é confiável?', a: 'Não há garantia publicada de limite de taxa nem SLA de disponibilidade para o modo gratuito padrão. O próprio rastreador de issues do tgpt documenta erros repetidos de limite de taxa e de gateway em backends gratuitos ao longo de sua história, motivo pelo qual existe uma flag de fallback `--rotate`.' },
          { q: 'Posso usar minha própria chave de API com o tgpt?', a: 'Sim, o tgpt é compatível com opções de chave de API própria para provedores incluindo OpenAI, DeepSeek, Groq e Gemini, via flag `--provider`.' },
          { q: 'Quem mantém o tgpt?', a: 'Um desenvolvedor conhecido pelo usuário do GitHub aandrew-me, com o repositório criado em 17 de abril de 2023.' },
          { q: 'Sob qual licença o tgpt é lançado?', a: 'GNU General Public License v3.0 (GPLv3), confirmada pelo arquivo LICENSE do repositório.' },
          { q: 'O tgpt gera comandos de shell como o shell-gpt?', a: 'Sim, a flag `-s`/`--shell` do tgpt gera comandos de shell adaptados ao sistema operacional a partir de solicitações em linguagem natural, semelhante em espírito ao recurso principal do shell-gpt.' },
          { q: 'O tgpt é compatível com geração de imagens?', a: 'Sim, via sua flag `-img`/`--image`, usando provedores incluindo pollinations, magicstudio e anyapi, segundo sua própria documentação.' },
          { q: 'O tgpt é um agente de codificação autônomo?', a: 'Não, o tgpt gera respostas de chat, comandos de shell e trechos de código — ele não realiza alterações autônomas multi-arquivo de um projeto.' },
          { q: 'A PromptQuorum testou de forma independente as alegações do tgpt?', a: 'Esta review se baseia no próprio repositório do GitHub do tgpt, seu README, sua documentação interna e seu rastreador público de issues, em vez de benchmarks práticos realizados pela PromptQuorum.' },
          { q: 'O tgpt é o mesmo que o ChatGPT?', a: 'Não. O tgpt é um programa de terminal independente e de código aberto, mantido por aandrew-me, e não um produto da OpenAI. Ele só acessa os modelos da OpenAI se você escolher o provedor `openai` e informar sua própria chave de API.' },
          { q: 'O tgpt é oficial e onde posso obtê-lo?', a: 'A fonte oficial é o repositório do projeto no GitHub, [github.com/aandrew-me/tgpt](https://github.com/aandrew-me/tgpt), onde estão os comandos de instalação. Ele só é "oficial" como projeto do seu mantenedor; não é um cliente oficial do ChatGPT, da OpenAI nem de outro provedor de IA.' },
          { q: 'Preciso fazer login ou criar uma conta para usar o tgpt?', a: 'Não. O tgpt não tem login nem conta. No modo padrão ele usa uma chave pública compartilhada: basta instalar e digitar um prompt. Só os provedores em que você traz a sua chave, como OpenAI ou DeepSeek, exigem uma chave desse provedor.' },
          { q: 'Qual modelo de IA o tgpt usa?', a: 'Depende do provedor. O provedor gratuito padrão, "opencode", mudou de modelo entre versões — a documentação do projeto cita deepseek-v4-flash-free e o padrão embutido no código-fonte é `big-pickle`. Defina `OPENCODE_MODEL` para fixar um, ou escolha outro provedor com `--provider`.' },
          { q: 'O tgpt é realmente gratuito?', a: 'O programa é gratuito e licenciado sob a GPLv3, e o modo padrão não custa nada nem exige chave. Os provedores conectados com a sua própria chave cobram diretamente de você, e o backend gratuito padrão não tem garantia de limite de uso publicada.' },
          { q: 'O tgpt funciona no Linux e em um Chromebook?', a: 'O Linux é uma plataforma compatível: use o script de instalação, `pacman -S tgpt` no Arch Linux, Homebrew ou Go. Um Chromebook com Linux (Crostini) ativado executa programas Linux, então a instalação para Linux deve servir, mas a PromptQuorum não testou o tgpt em um Chromebook.' },
          { q: 'O que significa o erro "Invalid provider" no tgpt?', a: 'Significa que o nome passado a `--provider` não é um provedor compatível. Use o nome exato em minúsculas da [lista de provedores](https://github.com/aandrew-me/tgpt/blob/main/md/providers.md), por exemplo `opencode`, `pollinations` ou `groq`.' },
          { q: 'Por que o tgpt retorna erro ou nenhuma resposta?', a: 'Na maioria das vezes o backend gratuito padrão está indisponível ou limitado — um issue sobre isso ficou aberto de 14 a 23 de setembro de 2026 na v2.14.0, até a v2.15.0 trazer uma correção. Atualize o tgpt, teste `--rotate` ou outro provedor e verifique as configurações de rede ou proxy. Veja a seção de solução de problemas acima.' },
          { q: 'O que significa tgpt?', a: 'O README não define o nome; costuma ser lido como "terminal GPT". O repositório descreve o tgpt como uma ferramenta de CLI multiplataforma para usar IA no terminal.' },
        ],
      },
