        content: '**tgpt의 기본 제공자인 "opencode"는 개인 키가 아닌 공유 공개 API 키를 사용해, opencode.ai의 "zen" API에 있는 무료 공개 프록시로 프롬프트를 전달합니다 — 이것이 "API 키 불필요"의 전체 메커니즘입니다.**',
