        title: '자주 묻는 질문',
        faqs: [
          { q: 'tgpt란 무엇인가요?', a: 'tgpt([github.com/aandrew-me/tgpt](https://github.com/aandrew-me/tgpt))는 무료, 오픈소스(GPLv3), Go 기반의 명령줄 AI 챗봇 도구로, 기본적으로 자신의 API 키가 없어도 작동합니다.' },
          { q: 'tgpt는 API 키 없이 어떻게 작동하나요?', a: '기본 제공자인 "opencode"는 개인 계정이 아닌 공유 키를 사용해 무료 공개 프록시(opencode.ai의 "zen" API)로 프롬프트를 전달합니다 — 이는 구체적인 메커니즘이며, 어떤 제공자의 약관을 우회하는 것이 아닙니다.' },
          { q: 'tgpt의 무료 모드는 신뢰할 수 있나요?', a: '기본 무료 모드에는 공개된 속도 제한 보장이나 가동 시간 SLA가 없습니다. tgpt 자체 이슈 트래커에는 그 역사 전반에 걸쳐 무료 백엔드에서 반복적인 속도 제한 및 게이트웨이 오류가 기록되어 있으며, 이 때문에 `--rotate` 대체 플래그가 존재합니다.' },
          { q: 'tgpt에서 제 자체 API 키를 사용할 수 있나요?', a: '네, tgpt는 `--provider` 플래그를 통해 OpenAI, DeepSeek, Groq, Gemini 등의 제공자에 대한 자체 API 키 옵션을 지원합니다.' },
          { q: 'tgpt는 누가 관리하나요?', a: 'GitHub 핸들 aandrew-me로 알려진 개발자이며, 저장소는 2023년 4월 17일에 생성되었습니다.' },
          { q: 'tgpt는 어떤 라이선스로 공개되나요?', a: 'GNU General Public License v3.0(GPLv3), 저장소의 LICENSE 파일을 통해 확인됩니다.' },
          { q: 'tgpt도 shell-gpt처럼 셸 명령을 생성하나요?', a: '네, tgpt의 `-s`/`--shell` 플래그는 자연어 요청으로부터 운영체제를 인식하는 셸 명령을 생성하며, shell-gpt의 핵심 기능과 취지가 비슷합니다.' },
          { q: 'tgpt는 이미지 생성을 지원하나요?', a: '네, `-img`/`--image` 플래그를 통해 지원되며, 자체 문서에 따르면 pollinations, magicstudio, anyapi 등의 제공자를 사용합니다.' },
          { q: 'tgpt는 자율 코딩 에이전트인가요?', a: '아니요, tgpt는 채팅 응답, 셸 명령, 코드 스니펫을 생성할 뿐이며, 프로젝트에 대한 여러 파일에 걸친 자율적인 변경을 수행하지 않습니다.' },
          { q: 'PromptQuorum은 tgpt의 주장을 독자적으로 검증했나요?', a: '이 리뷰는 PromptQuorum의 실제 벤치마크가 아니라, tgpt 자체의 GitHub 저장소, README, 저장소 내 문서, 공개 이슈 트래커를 바탕으로 작성되었습니다.' },
          { q: 'tgpt는 ChatGPT와 같은 것인가요?', a: '아니요. tgpt는 aandrew-me가 관리하는 독립적인 오픈소스 터미널 프로그램이며 OpenAI의 제품이 아닙니다. `openai` 제공자를 선택하고 본인의 API 키를 입력할 때만 OpenAI 모델에 접근할 수 있습니다.' },
          { q: 'tgpt는 공식인가요? 어디서 받나요?', a: '공식 출처는 프로젝트의 GitHub 저장소 [github.com/aandrew-me/tgpt](https://github.com/aandrew-me/tgpt)이며 설치 명령도 거기에 나와 있습니다. 관리자 본인의 프로젝트라는 의미에서만 "공식"이고, ChatGPT, OpenAI 또는 다른 AI 제공자의 공식 클라이언트는 아닙니다.' },
          { q: 'tgpt를 쓰려면 로그인하거나 계정을 만들어야 하나요?', a: '아니요. tgpt에는 로그인도 계정도 없습니다. 기본 모드에서는 공유 공개 키를 사용하므로 설치하고 프롬프트를 입력하면 됩니다. OpenAI나 DeepSeek처럼 본인 키를 가져오는 제공자만 해당 제공자의 키가 필요합니다.' },
          { q: 'tgpt는 어떤 AI 모델을 사용하나요?', a: '제공자에 따라 다릅니다. 무료 기본 제공자 "opencode"는 릴리스마다 모델이 바뀌었으며, 프로젝트 문서에는 deepseek-v4-flash-free, 소스 코드에 내장된 기본값은 `big-pickle`입니다. `OPENCODE_MODEL`로 고정하거나 `--provider`로 다른 제공자를 고를 수 있습니다.' },
          { q: 'tgpt는 정말 무료인가요?', a: '프로그램은 무료이며 GPLv3 라이선스입니다. 기본 모드는 비용이 들지 않고 키도 필요 없습니다. 본인 키로 연결하는 제공자는 직접 비용을 청구하며, 무료 기본 백엔드에는 공개된 요청 한도 보장이 없습니다.' },
          { q: 'tgpt는 Linux와 Chromebook에서 작동하나요?', a: 'Linux는 지원 플랫폼입니다. 설치 스크립트, Arch Linux의 `pacman -S tgpt`, Homebrew, Go를 사용할 수 있습니다. Linux(Crostini)를 켠 Chromebook은 Linux 프로그램을 실행하므로 Linux 설치 방법이 적용될 것으로 보이지만, PromptQuorum은 Chromebook에서 tgpt를 테스트하지 않았습니다.' },
          { q: 'tgpt의 "Invalid provider" 오류는 무슨 뜻인가요?', a: '`--provider`에 전달한 이름이 지원되는 제공자가 아니라는 뜻입니다. [제공자 목록](https://github.com/aandrew-me/tgpt/blob/main/md/providers.md)에 있는 정확한 소문자 이름(예: `opencode`, `pollinations`, `groq`)을 사용하세요.' },
          { q: 'tgpt가 오류를 내거나 답변이 없는 이유는 무엇인가요?', a: '대부분 무료 기본 백엔드를 쓸 수 없거나 제한된 경우입니다. 이에 관한 이슈가 v2.14.0에서 2026년 9월 14일부터 23일까지 열려 있었고, v2.15.0에서 수정이 나왔습니다. tgpt를 업데이트하고 `--rotate`나 다른 제공자를 시도하며 네트워크·프록시 설정을 확인하세요. 위의 문제 해결 섹션도 참고하세요.' },
          { q: 'tgpt는 무엇의 약자인가요?', a: 'README에는 이름의 정의가 없으며 흔히 "terminal GPT"로 읽습니다. 저장소는 tgpt를 터미널에서 AI를 쓰기 위한 크로스 플랫폼 CLI 도구로 설명합니다.' },
        ],
